// Normalize Knowledge Records
// Converts POLICIES, PACKAGES, SUBJECTS, LOCATIONS and FAQ
// into one consistent structure for ranking and AI context.

const clean = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

const lower = (value) => clean(value).toLowerCase();
const upper = (value) => clean(value).toUpperCase();

let detection = {};

try {
  detection =
    $('Detect Knowledge Domain').first().json ?? {};
} catch (error) {
  detection = {};
}

const domain =
  upper(detection.knowledge_domain) || 'FAQ';

const detectedLanguage =
  lower(detection.language) || 'ar';

const sourceSheetMap = {
  POLICIES: 'POLICIES',
  PRICES: 'PACKAGES',
  SUBJECTS: 'SUBJECTS',
  LOCATIONS: 'LOCATIONS',
  SERVICES: 'FAQ',
  FAQ: 'FAQ',
};

const sourceSheet =
  sourceSheetMap[domain] || 'FAQ';

const inputRows = $input
  .all()
  .map((item) => item.json ?? {});

const normalizedRecords = [];

for (const row of inputRows) {
  // Ignore the empty item produced by Always Output Data.
  if (!row || Object.keys(row).length === 0) {
    continue;
  }

  const status = upper(row.status);

  // Only verified ACTIVE records are allowed.
  if (status !== 'ACTIVE') {
    continue;
  }

  const language =
    lower(row.language) || detectedLanguage;

  // Safety check in case the Google Sheets filter wasn't applied.
  if (
    detectedLanguage &&
    language &&
    language !== detectedLanguage
  ) {
    continue;
  }

  let question = '';
  let answer = '';
  let keywords = '';
  let category = lower(domain);
  let metadata = {};

  switch (domain) {
    case 'POLICIES': {
      const policyType = clean(row.policy_type);
      const rule = clean(row.rule);
      const customerAnswer = clean(row.customer_answer);

      question = [policyType, rule]
        .filter(Boolean)
        .join(' — ');

      answer = customerAnswer || rule;
      keywords = clean(row.keywords);
      category = policyType || 'policies';

      metadata = {
        policy_type: policyType,
        rule,
        last_reviewed: clean(row.last_reviewed),
      };

      break;
    }

    case 'PRICES': {
      const packageName = clean(row.package_name);
      const classCount = clean(row.class_count);
      const price = clean(row.price);
      const currency = clean(row.currency);
      const answerText = clean(row.answer_text);

      question =
        packageName ||
        (classCount
          ? `${classCount} lessons package`
          : 'Package price');

      const packageFacts = [
        packageName,
        classCount
          ? `class_count: ${classCount}`
          : '',
        price
          ? `price: ${price}`
          : '',
        currency
          ? `currency: ${currency}`
          : '',
      ]
        .filter(Boolean)
        .join(' | ');

      answer = answerText
        ? `${answerText} | ${packageFacts}`
        : packageFacts;

      keywords = clean(row.keywords);
      category = 'prices';

      metadata = {
        package_name: packageName,
        class_count: classCount,
        price,
        currency,
        last_reviewed: clean(row.last_reviewed),
      };

      break;
    }

    case 'SUBJECTS': {
      const subject = clean(row.subject);
      const gradeFrom = clean(row.grade_from);
      const gradeTo = clean(row.grade_to);
      const deliveryMode = clean(row.delivery_mode);
      const description = clean(row.description);

      question = subject || 'Available subjects';

      const subjectFacts = [
        subject
          ? `subject: ${subject}`
          : '',
        gradeFrom
          ? `grade_from: ${gradeFrom}`
          : '',
        gradeTo
          ? `grade_to: ${gradeTo}`
          : '',
        deliveryMode
          ? `delivery_mode: ${deliveryMode}`
          : '',
      ]
        .filter(Boolean)
        .join(' | ');

      answer = description
        ? `${description} | ${subjectFacts}`
        : subjectFacts;

      keywords = clean(row.keywords);
      category = 'subjects';

      metadata = {
        subject,
        grade_from: gradeFrom,
        grade_to: gradeTo,
        delivery_mode: deliveryMode,
      };

      break;
    }

    case 'LOCATIONS': {
      const country = clean(row.country);
      const region = clean(row.region);
      const city = clean(row.city);
      const serviceNote = clean(row.service_note);

      question = [city, region, country]
        .filter(Boolean)
        .join(', ');

      const locationFacts = [
        country
          ? `country: ${country}`
          : '',
        region
          ? `region: ${region}`
          : '',
        city
          ? `city: ${city}`
          : '',
      ]
        .filter(Boolean)
        .join(' | ');

      answer = serviceNote
        ? `${serviceNote} | ${locationFacts}`
        : locationFacts;

      keywords = clean(row.keywords);
      category = 'locations';

      metadata = {
        country,
        region,
        city,
      };

      break;
    }

    case 'SERVICES':
    case 'FAQ':
    default: {
      question = clean(
        row.question ||
        row.normalized_question
      );

      answer = clean(
        row.answer ||
        row.approved_answer
      );

      keywords = clean(row.keywords);

      category =
        clean(row.category) ||
        lower(domain);

      metadata = {
        priority: clean(row.priority),
        last_reviewed: clean(row.last_reviewed),
      };

      break;
    }
  }

  // Never send an empty or unverifiable record to the AI.
  if (!answer) {
    continue;
  }

  normalizedRecords.push({
    record_id: clean(
      row.record_id ||
      row.question_id
    ),

    source_domain: domain,
    source_sheet: sourceSheet,
    language,

    question,
    normalized_question:
      lower(row.normalized_question || question),

    answer,
    keywords,
    category,

    priority: clean(row.priority),
    status: 'ACTIVE',
    knowledge_empty: false,
    metadata,
  });
}

// Remove duplicate questions.
// If the same question appears more than once, the later row wins.
const uniqueRecords = new Map();

for (const record of normalizedRecords) {
  const deduplicationKey = [
    record.language,
    record.category,
    record.normalized_question,
  ].join('|');

  uniqueRecords.set(
    deduplicationKey,
    record
  );
}

const finalRecords = Array.from(
  uniqueRecords.values()
);

// Keep the workflow running if no verified result was found.
if (finalRecords.length === 0) {
  return [
    {
      json: {
        record_id: '',
        source_domain: domain,
        source_sheet: sourceSheet,
        language: detectedLanguage,
        question: '',
        normalized_question: '',
        answer: '',
        keywords: '',
        category: lower(domain),
        priority: '',
        status: 'ACTIVE',
        knowledge_empty: true,
        metadata: {},
      },
    },
  ];
}

return finalRecords.map((record) => ({
  json: record,
}));

const clean = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

const normalize = (value) =>
  clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[\u064B-\u065F\u0670]/g, '')
    .replace(/ـ/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const stopWords = new Set([
  'هل', 'ما', 'ماذا', 'كيف', 'كم', 'في', 'من', 'الي',
  'علي', 'عن', 'بعد', 'قبل', 'هذا', 'هذه', 'التي', 'الذي',
  'عند', 'لدي', 'لدينا', 'لديكم', 'تقدمون', 'توفرون',
  'طالب', 'طلاب', 'ابني', 'ابنتي', 'خدمه', 'خدمات',
  'خدماتكم', 'اريد', 'يمكن', 'يمكنكم',

  'the', 'a', 'an', 'is', 'are', 'do', 'does', 'how',
  'what', 'which', 'where', 'when', 'for', 'to', 'of',
  'in', 'on', 'after', 'before', 'you', 'your', 'offer',
  'provide', 'student', 'students',

  'le', 'la', 'les', 'un', 'une', 'des', 'de', 'du',
  'dans', 'pour', 'vous', 'votre', 'offrez', 'proposez',
  'eleve', 'eleves'
]);

const tokenize = (value) => {
  return [...new Set(
    normalize(value)
      .split(' ')
      .map((token) => {
        if (
          /^[\u0600-\u06FF]+$/u.test(token) &&
          token.startsWith('ال') &&
          token.length > 4
        ) {
          return token.slice(2);
        }

        return token;
      })
      .filter((token) => {
        return (
          token.length >= 2 &&
          !stopWords.has(token)
        );
      })
  )];
};

const intersectionCount = (left, right) => {
  const rightSet = new Set(right);
  return left.filter((token) => rightSet.has(token)).length;
};

let triggerData = {};
let detectionData = {};

try {
  triggerData =
    $('When chat message received').first().json ?? {};
} catch (error) {
  triggerData = {};
}

try {
  detectionData =
    $('Detect Knowledge Domain').first().json ?? {};
} catch (error) {
  detectionData = {};
}

const customerMessage = clean(
  triggerData.chatInput ||
  detectionData.customer_message
);

const queryNormalized = normalize(customerMessage);
const queryTokens = tokenize(customerMessage);

const domain = clean(
  detectionData.knowledge_domain || 'FAQ'
).toUpperCase();

const language = clean(
  detectionData.language ||
  triggerData.metadata?.locale ||
  'ar'
).toLowerCase();

const records = $input
  .all()
  .map((item) => item.json ?? {})
  .filter((row) => {
    return (
      row.knowledge_empty !== true &&
      clean(row.status).toUpperCase() === 'ACTIVE' &&
      clean(row.answer) !== ''
    );
  });

const scoredRecords = records.map((row) => {
  const recordQuestion = normalize(row.question);
  const questionTokens = tokenize(row.question);
  const keywordTokens = tokenize(row.keywords);
  const categoryTokens = tokenize(row.category);
  const answerTokens = tokenize(row.answer);

  let score = 0;

  if (
    recordQuestion &&
    queryNormalized === recordQuestion
  ) {
    score += 100;
  } else if (
    recordQuestion.length >= 8 &&
    (
      queryNormalized.includes(recordQuestion) ||
      recordQuestion.includes(queryNormalized)
    )
  ) {
    score += 40;
  }

  score +=
    intersectionCount(queryTokens, questionTokens) * 4;

  score +=
    intersectionCount(queryTokens, keywordTokens) * 7;

  score +=
    intersectionCount(queryTokens, categoryTokens) * 5;

  score +=
    intersectionCount(queryTokens, answerTokens);

  const keywordPhrases = clean(row.keywords)
    .split(/[,،;|]/)
    .map((keyword) => normalize(keyword))
    .filter((keyword) => keyword.length >= 3);

  for (const phrase of keywordPhrases) {
    if (queryNormalized.includes(phrase)) {
      score += 20;
    }
  }

  return {
    ...row,
    relevance_score: score,
  };
});

const genericPatterns = {
  SUBJECTS: [
    /ما المواد/,
    /اي مواد/,
    /المواد التي/,
    /\bsubjects?\b/,
    /quelles matieres/
  ],

  PRICES: [
    /كم سعر/,
    /ما السعر/,
    /الاسعار/,
    /\bprices?\b/,
    /\bcost\b/,
    /\bpackages?\b/,
    /\bprix\b/,
    /\btarifs?\b/
  ],

  POLICIES: [
    /ما سياسات/,
    /ما هي سياسات/,
    /\bpolicies\b/,
    /\bpolicy\b/,
    /quelles politiques/
  ],

  LOCATIONS: [
    /اين تقدمون/,
    /ما المدن/,
    /ما المناطق/,
    /\bwhere do you serve\b/,
    /\blocations?\b/,
    /quelles villes/
  ]
};

const isGenericDomainQuestion =
  Boolean(genericPatterns[domain]) &&
  genericPatterns[domain].some((pattern) =>
    pattern.test(queryNormalized)
  ) &&
  queryTokens.length <= 3;

let matches = scoredRecords
  .filter((row) => row.relevance_score >= 8)
  .sort((a, b) =>
    b.relevance_score - a.relevance_score
  )
  .slice(0, 4);

if (
  matches.length === 0 &&
  isGenericDomainQuestion
) {
  matches = scoredRecords
    .map((row) => ({
      ...row,
      relevance_score: 10,
    }))
    .slice(0, 6);
}

if (matches.length === 0) {
  return [
    {
      json: {
        record_id: '',
        source_domain: domain,
        source_sheet: '',
        language,
        question: '',
        normalized_question: '',
        answer: '',
        keywords: '',
        category: domain.toLowerCase(),
        priority: '',
        status: 'ACTIVE',
        knowledge_empty: true,
        relevance_score: 0,
        metadata: {},
      },
    },
  ];
}

return matches.map((record) => ({
  json: record,
}));

// Aggregate Knowledge Context

const clean = (value) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

let triggerData = {};
let detectionData = {};

try {
  triggerData =
    $('When chat message received').first().json ?? {};
} catch (error) {
  triggerData = {};
}

try {
  detectionData =
    $('Detect Knowledge Domain').first().json ?? {};
} catch (error) {
  detectionData = {};
}

const records = $input
  .all()
  .map((item) => item.json ?? {})
  .filter((row) => {
    return (
      row.knowledge_empty !== true &&
      clean(row.status).toUpperCase() === 'ACTIVE' &&
      clean(row.answer) !== ''
    );
  })
  .map((row) => ({
    record_id: clean(row.record_id),
    category: clean(row.category),
    question: clean(row.question),
    answer: clean(row.answer),
    keywords: clean(row.keywords),
  }));

const knowledgeContext = JSON.stringify(records);

return [
  {
    json: {
      customer_message: clean(
        triggerData.chatInput ||
        detectionData.customer_message
      ),

      session_id: clean(
        triggerData.sessionId ||
        detectionData.session_id
      ),

      language: clean(
        detectionData.language ||
        triggerData.metadata?.locale ||
        'ar'
      ),

      knowledge_domain: clean(
        detectionData.knowledge_domain ||
        'FAQ'
      ),

      knowledge_found: records.length > 0,
      knowledge_count: records.length,

      knowledge_context: knowledgeContext,

      // Kept temporarily for compatibility with the current prompt.
      faq_context: knowledgeContext,

      metadata: triggerData.metadata ?? {},
    },
  },
];

const originalText = String(
  $json.chatInput ??
  $json.customer_message ??
  $json.message ??
  ''
).trim();

function normalizeText(value) {
  return value
    .toLowerCase()
    .normalize('NFKC')
    .replace(/[\u064B-\u065F\u0670]/g, '')
    .replace(/[إأآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/[؟?!.,،؛:ـ"'()[\]{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const text = normalizeText(originalText);

const greetingPatterns = [
  /^(السلام عليكم|السلام عليكم ورحمة الله|السلام عليكم ورحمة الله وبركاته)$/,
  /^(السلام عليكم كيف حالكم|السلام عليكم كيفكم)$/,
  /^(وعليكم السلام|وعليكم السلام ورحمة الله|وعليكم السلام ورحمة الله وبركاته)$/,
  /^(سلام|مرحبا|اهلا|اهلا وسهلا|صباح الخير|مساء الخير)$/,
  /^(hello|hi|hey|good morning|good afternoon|good evening)$/,
  /^(bonjour|bonsoir|salut)$/
];

const thanksPatterns = [
  /^(شكرا|شكرا لك|جزاك الله خيرا|بارك الله فيك)$/,
  /^(thank you|thanks|many thanks)$/,
  /^(merci|merci beaucoup)$/
];

const goodbyePatterns = [
  /^(مع السلامة|في امان الله|الى اللقاء)$/,
  /^(goodbye|bye|see you)$/,
  /^(au revoir|a bientot)$/
];

const isGreeting = greetingPatterns.some(pattern => pattern.test(text));
const isThanks = thanksPatterns.some(pattern => pattern.test(text));
const isGoodbye = goodbyePatterns.some(pattern => pattern.test(text));

let conversationalIntent = 'none';
let directResponse = '';

if (isGreeting) {
  conversationalIntent = 'greeting';

  if (/^(hello|hi|hey|good morning|good afternoon|good evening)$/.test(text)) {
    directResponse =
      'Welcome to Success Path Mentors. How may I assist you with your child’s learning today?';
  } else if (/^(bonjour|bonsoir|salut)$/.test(text)) {
    directResponse =
      'Bienvenue chez Success Path Mentors. Comment puis-je vous aider concernant les besoins scolaires de votre enfant ?';
  } else {
    directResponse =
      'وعليكم السلام ورحمة الله وبركاته، أهلاً بكم في Success Path Mentors. كيف يمكنني مساعدتكم بخصوص احتياجات الطالب الدراسية؟';
  }
}

if (isThanks) {
  conversationalIntent = 'thanks';

  if (/^(thank you|thanks|many thanks)$/.test(text)) {
    directResponse =
      'You’re welcome. Is there anything else I can help you with?';
  } else if (/^(merci|merci beaucoup)$/.test(text)) {
    directResponse =
      'Avec plaisir. Puis-je vous aider avec autre chose ?';
  } else {
    directResponse =
      'العفو، بارك الله فيكم. هل يمكنني مساعدتكم في أمر آخر؟';
  }
}

if (isGoodbye) {
  conversationalIntent = 'goodbye';

  if (/^(goodbye|bye|see you)$/.test(text)) {
    directResponse =
      'Thank you for contacting Success Path Mentors. Have a wonderful day.';
  } else if (/^(au revoir|a bientot)$/.test(text)) {
    directResponse =
      'Merci d’avoir contacté Success Path Mentors. À bientôt.';
  } else {
    directResponse =
      'شكرًا لتواصلكم مع Success Path Mentors. في أمان الله.';
  }
}

return {
  json: {
    ...$json,
    original_message: originalText,
    normalized_message: text,
    conversational_intent: conversationalIntent,
    is_conversational: conversationalIntent !== 'none',
    direct_response: directResponse
  }
};

// جميع الصفوف القادمة من عقدة Load Active Intent Catalog
const sheetRows = $input.all().map(item => item.json);

// استرجاع بيانات الرسالة بعد فحص التحية
let messageData = {};

try {
  messageData =
    $('Detect Conversational Message').first().json;
} catch (error) {
  // احتياطياً نستخدم بيانات Chat Trigger مباشرة
  messageData =
    $('When chat message received').first().json;
}

// تحويل قائمة الحقول المطلوبة إلى Array
function parseRequiredEntities(value) {
  if (!value) return [];

  return String(value)
    .split(/[,،;|\n]/)
    .map(value => value.trim())
    .filter(Boolean);
}

// تنظيف وتجميع النوايا النشطة
const activeIntents = sheetRows
  .filter(row => {
    const status = String(row.status || '')
      .trim()
      .toUpperCase();

    return status === 'ACTIVE';
  })
  .map(row => ({
    intent_id: String(row.intent_id || '').trim(),
    intent_name: String(row.intent_name || '').trim(),
    category: String(row.category || '').trim(),
    description: String(row.description || '').trim(),

    examples_ar: String(row.examples_ar || '').trim(),
    examples_en: String(row.examples_en || '').trim(),
    examples_fr: String(row.examples_fr || '').trim(),

    required_entities: parseRequiredEntities(
      row.required_entities
    ),

    next_action: String(row.next_action || '').trim(),

    priority: Number.isFinite(Number(row.priority))
      ? Number(row.priority)
      : 99
  }))
  .filter(intent => intent.intent_name !== '')
  .sort((a, b) => a.priority - b.priority);

// استخراج رسالة العميل
const customerMessage = String(
  messageData.chatInput ??
  messageData.customer_message ??
  messageData.original_message ??
  messageData.message ??
  ''
).trim();

// استخراج Session ID
const sessionId = String(
  messageData.sessionId ??
  messageData.session_id ??
  ''
).trim();

// إعادة Item واحد فقط
return [
  {
    json: {
      ...messageData,

      customer_message: customerMessage,
      session_id: sessionId,

      intent_catalog: activeIntents,

      // سنستخدم هذا الحقل لاحقاً داخل Prompt
      intent_catalog_text: JSON.stringify(activeIntents),

      intent_count: activeIntents.length,
      intent_catalog_loaded: activeIntents.length > 0,

      intent_catalog_error:
        activeIntents.length > 0
          ? ''
          : 'No ACTIVE intents were found in INTENT_CATALOG'
    }
  }
];

