parameters.jsCode:
// Basic LLM Chain currently returns the classification inside "output"
const raw =
  $json.output ??
  $json.text ??
  $json;

// Recover the original message and intent catalog without paired-item lookup
const context =
  $('Build Intent Context').first().json;

const intentCatalog = Array.isArray(context.intent_catalog)
  ? context.intent_catalog
  : [];

function clean(value) {
  return String(value ?? '').trim();
}

// ------------------------------
// 1. Validate primary intent
// ------------------------------

const primaryIntent = clean(raw.primary_intent);

const matchedIntent = intentCatalog.find(
  row => clean(row.intent_name) === primaryIntent
);

const intentExists = Boolean(matchedIntent);

// ------------------------------
// 2. Validate confidence
// ------------------------------

const originalConfidence = Number(raw.confidence);

const confidenceIsValid =
  Number.isFinite(originalConfidence) &&
  originalConfidence >= 0 &&
  originalConfidence <= 1;

const confidence = confidenceIsValid
  ? originalConfidence
  : 0;

// ------------------------------
// 3. Validate language
// ------------------------------

const allowedLanguages = new Set([
  'ar',
  'en',
  'fr'
]);

const originalLanguage = clean(raw.language);

const language = allowedLanguages.has(originalLanguage)
  ? originalLanguage
  : 'ar';

// ------------------------------
// 4. Normalize entities
// ------------------------------

const entityKeys = [
  'age',
  'grade',
  'subject',
  'current_level',
  'difficulty',
  'goal',
  'country',
  'city',
  'timezone',
  'preferred_schedule'
];

const rawEntities =
  raw.entities &&
  typeof raw.entities === 'object' &&
  !Array.isArray(raw.entities)
    ? raw.entities
    : {};

const entities = {};

for (const key of entityKeys) {
  entities[key] = clean(rawEntities[key]);
}

// ------------------------------
// 5. Recalculate missing entities
// ------------------------------

const requiredEntities = Array.isArray(
  matchedIntent?.required_entities
)
  ? matchedIntent.required_entities
      .map(clean)
      .filter(Boolean)
  : [];

const missingEntities = requiredEntities.filter(
  key => !clean(entities[key] ?? rawEntities[key])
);

// ------------------------------
// 6. Normalize knowledge domain
// ------------------------------

const domainByIntent = {
  'pricing.ask': 'packages',
  'subjects.ask': 'subjects',
  'student_support.ask': 'subjects',
  'policy.ask': 'policies',
  'location.ask': 'locations',
  'knowledge.ask': 'faq'
};

