      /مدينتي/,
      /\bcity\b/,
      /\bville\b/
    ]
  },
  {
    field: 'timezone',
    patterns: [
      /المنطقه الزمنيه/,
      /التوقيت/,
      /time zone/,
      /timezone/,
      /fuseau horaire/
    ]
  },
  {
    field: 'preferred_language',
    patterns: [
      /اللغه المفضله/,
      /لغه التواصل/,
      /preferred language/,
      /langue preferee/
    ]
  },
  {
    field: 'grade',
    patterns: [
      /الصف/,
      /المرحله الدراسيه/,
      /\bgrade\b/,
      /niveau scolaire/
    ]
  },
  {
    field: 'subject',
    patterns: [
      /الماده/,
      /الموضوع الدراسي/,
      /\bsubject\b/,
      /matiere/
    ]
  }
];

if (!leadUpdateField) {
  for (const definition of leadFieldDefinitions) {
    if (
      definition.patterns.some(pattern => {
        return pattern.test(
          normalizedCustomerMessage
        );
      })
    ) {
      leadUpdateField = definition.field;
      break;
    }
  }
}

if (
  !leadUpdateField &&
  previousAwaitingEntity.startsWith(
    'lead_update_'
  )
) {
  leadUpdateField =
    previousAwaitingEntity.replace(
      'lead_update_',
      ''
    );
}

const updateVerbPattern =
  /(اريد|اود|حاب|ارغب)?\s*(تعديل|تغيير|تصحيح|تحديث|استبدال)|غير بريدي|صحح بياناتي|update|change|correct|modify|replace|modifier|changer|corriger|mettre a jour/;

const generalLeadDataPattern =
  /(بياناتي|معلوماتي|بيانات التسجيل|بيانات الطالب|my data|my details|registration details|mes donnees|mes informations)/;

const updateRequestDetected =
  updateVerbPattern.test(
    normalizedCustomerMessage
  ) &&
  Boolean(
    leadUpdateField ||
    generalLeadDataPattern.test(
      normalizedCustomerMessage
    )
  );

// استخراج القيمة عندما يرسل العميل التصحيح في الرسالة
// نفسها، مثل: أريد تغيير بريدي إلى new@example.com.
if (!leadUpdateValue && leadUpdateField === 'email') {
  const emailMatch = originalCustomerMessage.match(
    /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/
  );

  leadUpdateValue = clean(
    emailMatch?.[0]
  );
}

if (!leadUpdateValue && leadUpdateField === 'phone') {
  const phoneMatch = originalCustomerMessage.match(
    /\+?\d[\d\s().-]{6,}\d/
  );

  leadUpdateValue = clean(
    phoneMatch?.[0]
  );
}

if (
  !leadUpdateValue &&
  leadUpdateField &&
  !['email', 'phone'].includes(
    leadUpdateField
  )
) {
  const genericValueMatch =
    originalCustomerMessage.match(
      /(?:إلى|الى|to|as|vers|par)\s+(.+)$/i
    );

  leadUpdateValue = clean(
    genericValueMatch?.[1]
  );
}

let leadManagementRoute =
  leadManagementRouteFromInput;

if (leadConfirmationAccepted) {
  leadManagementRoute = 'confirmation';
} else if (
  previousAwaitingEntity ===
    'lead_update_unspecified'
) {
  leadManagementRoute =
    leadUpdateField && leadUpdateValue
      ? 'update_value'
      : 'update_request';
} else if (
  previousAwaitingEntity.startsWith(
    'lead_update_'
  )
) {
  const currentValueIsValid =
    leadUpdateField === 'email'
      ? Boolean(leadUpdateValue)
      : leadUpdateField === 'phone'
        ? Boolean(leadUpdateValue)
        : Boolean(originalCustomerMessage);

  leadManagementRoute =
    currentValueIsValid
      ? 'update_value'
      : 'update_request';
} else if (
  updateRequestDetected &&
  leadUpdateValue
) {
  leadManagementRoute = 'update_value';
} else if (updateRequestDetected) {
  leadManagementRoute = 'update_request';
}

if (leadManagementRoute === 'confirmation') {
  effectiveIntent = 'lead.confirmation';
} else if (leadManagementRoute === 'update_value') {
  effectiveIntent = 'lead.update.value';
} else if (leadManagementRoute === 'update_request') {
  effectiveIntent = 'lead.update.request';
}

const leadSummaryPatterns = [
  /^(ما هي|ما|ماذا).*(بياناتي|معلوماتي)/,
  /^(اعرض|اظهر|ارني|راجع).*(بياناتي|معلوماتي)/,
  /البيانات.*(سجلت|سجلتها|المسجله|المحفوظة|المحفوظات)/,
  /ماذا.*(سجلت|حفظت).*عني/,
  /^(show|display|review).*(my )?(data|details|information)/,
  /^what.*(data|details|information).*(recorded|saved)/,
  /^(affichez|montrez|verifiez).*(mes )?(donnees|informations)/,
  /^quelles.*(donnees|informations).*(enregistrees|sauvegardees)/
];

const isLeadSummaryRequest =
  !leadManagementRoute &&
  (
    effectiveIntent === 'lead.summary.request' ||
    leadSummaryPatterns.some(pattern => {
      return pattern.test(normalizedCustomerMessage);
    })
  );

if (isLeadSummaryRequest) {
  effectiveIntent = 'lead.summary.request';
}

const decision = {
  effective_intent: effectiveIntent,

  lead_management_route:
    leadManagementRoute,

  lead_update_field:
    leadUpdateField,

  lead_update_value:
    leadUpdateValue,

  lead_confirmation_accepted:
    leadConfirmationAccepted,

  route_key: 'knowledge',

  next_best_action: 'search_knowledge',

  action_type: 'knowledge_search',

  awaiting_entity:
    clean(state.awaiting_entity),

  next_question: '',

  nurture_fact_key: '',

  should_search_knowledge: true,

  should_reveal_price: false,

  should_start_conversion: false,

  should_start_handoff: false,

  decision_missing_entities: [],

  requires_clarification: false,

  objection_followup_handled: false,

  objection_resolution_action:
    objectionResolutionAction,

  objection_response_variant:
    objectionResponseVariant,

  nurture_fact_already_shared: false,

  question_already_asked: false
};

function configureQuestion(
  entity,
  action,
  factKey,
  remainingFields
) {
  decision.route_key =
    'sales_discovery';

  decision.next_best_action = action;

  decision.action_type =
    'ask_discovery_question';

  decision.awaiting_entity = entity;

  decision.next_question =
    questions[language][entity] || '';

  decision.nurture_fact_key = factKey;

  decision.should_search_knowledge = true;

  decision.should_reveal_price = false;

  decision.decision_missing_entities =
    remainingFields;

  decision.requires_clarification = true;
}

function configurePricingDiscovery() {
  state.sales_stage = 'pricing';

  const discoveryFields = [
    'grade_or_age',
    'subject',
    'current_level',
    'country'
  ];

  const missing = allMissing(
    discoveryFields
  );

  const nextField = firstMissing(
    discoveryFields
  );

  if (nextField) {
    const actionMap = {
      grade_or_age: 'ask_grade_or_age',
      subject: 'ask_subject',
      current_level: 'ask_current_level',
      country: 'ask_country'
    };

    const factMap = {
      grade_or_age: 'personalized_assessment',
      subject: 'curriculum_alignment',
      current_level: 'diagnostic_support',
      country: 'online_one_to_one'
    };

    configureQuestion(
      nextField,
      actionMap[nextField],
      factMap[nextField],
      missing
    );

    return;
  }

  decision.route_key = 'pricing_ready';

  decision.next_best_action =
    'present_verified_pricing';

  decision.action_type =
    'verified_price_response';

  decision.awaiting_entity = '';

  decision.nurture_fact_key = 'pricing';

  decision.should_search_knowledge = true;

  decision.should_reveal_price = true;

  decision.decision_missing_entities = [];

  decision.requires_clarification = false;
}

function configureResolvedObjection() {
  state.sales_stage = 'objection_resolved';

  // الوقت المفضل وحده لا يكفي.
  // يجب معرفة المنطقة الزمنية قبل متابعة الحجز.
  if (
    activeObjection === 'objection.schedule' &&
    !clean(state.timezone)
  ) {
    configureQuestion(
      'timezone',
      'ask_timezone',
      'objection.schedule',
      ['timezone']
    );

    decision.objection_followup_handled = true;
    state.sales_stage = 'objection_resolved';
    return;
  }

  decision.route_key = 'objection';

  decision.next_best_action =
    objectionResolutionAction ||
    'resolve_objection';

  decision.action_type =
    'objection_resolution_response';

  const variantFactMap = {
    'objection.online:focus_concern':
      'objection.online.focus_concern',

    'objection.online:in_person_preference':
      'objection.online.in_person_preference',

    'objection.online:general_online_concern':
      'objection.online.general_online_concern',

    'objection.tutor:tutor_experience':
      'objection.tutor.tutor_experience',

    'objection.tutor:tutor_matching':
      'objection.tutor.tutor_matching',

    'objection.tutor:general_tutor_concern':
      'objection.tutor.general_tutor_concern',

    'objection.schedule:schedule_preference':
      'objection.schedule.schedule_preference'
  };

  const variantLookupKey =
    `${activeObjection}:${objectionResponseVariant}`;

  decision.nurture_fact_key =
    variantFactMap[variantLookupKey] ||
    activeObjection;

  decision.next_question =
    questions[language].trial_offer;

  decision.awaiting_entity =
    'trial_interest';

  decision.should_search_knowledge = false;

  decision.should_reveal_price = false;

  decision.should_start_conversion = false;

  decision.should_start_handoff = false;

  decision.decision_missing_entities = [];

  decision.requires_clarification = true;

  decision.objection_followup_handled = true;

  state.awaiting_entity =
    decision.awaiting_entity;

  state.last_question =
    decision.next_question;

  state.next_action =
    decision.next_best_action;

  state.questions_asked = unique([
    ...(state.questions_asked || []),
    decision.next_question
  ]);
}

// طلب تعديل بيانات محفوظة، دون إرسال القيمة الجديدة
// في الرسالة الحالية.
if (effectiveIntent === 'lead.update.request') {
  const targetField =
    leadUpdateField || 'unspecified';

  state.sales_stage = 'conversion';
  state.awaiting_entity =
    `lead_update_${targetField}`;
  state.next_action =
    'collect_lead_correction';

  decision.route_key = 'conversion';
  decision.next_best_action =
    'collect_lead_correction';
  decision.action_type =
    'lead_correction_request';
  decision.awaiting_entity =
    state.awaiting_entity;
  decision.next_question = '';
  decision.nurture_fact_key = '';
  decision.should_search_knowledge = false;
  decision.should_reveal_price = false;
  decision.should_start_conversion = true;
  decision.should_start_handoff = false;
  decision.decision_missing_entities = [];
  decision.requires_clarification = true;
}

// استلام القيمة الجديدة بعد طلب التعديل، أو استلام
// طلب التعديل والقيمة الجديدة في الرسالة نفسها.
else if (effectiveIntent === 'lead.update.value') {
  state.sales_stage = 'conversion';
  state.awaiting_entity =
    'lead_final_confirmation';
  state.next_action =
    'show_updated_lead_summary';

  decision.route_key = 'conversion';
  decision.next_best_action =
    'show_updated_lead_summary';
  decision.action_type =
    'lead_correction_value';
  decision.awaiting_entity =
    state.awaiting_entity;
  decision.next_question = '';
  decision.nurture_fact_key = '';
  decision.should_search_knowledge = false;
  decision.should_reveal_price = false;
  decision.should_start_conversion = true;
  decision.should_start_handoff = false;
  decision.decision_missing_entities = [];
  decision.requires_clarification = false;
}

// الموافقة النهائية. تقبل العبارة الكاملة، كما تقبل
// ردًا طبيعيًا واضحًا عندما يكون النظام بالفعل في
// انتظار تأكيد الملخص والموافقة على التواصل.
else if (effectiveIntent === 'lead.confirmation') {
  state.sales_stage = 'conversion';
  state.awaiting_entity = '';
  state.next_action =
    'submit_validated_handoff';

  decision.route_key = 'conversion';
  decision.next_best_action =
    'submit_validated_handoff';
  decision.action_type =
    'submit_validated_handoff';
  decision.awaiting_entity = '';
  decision.next_question = '';
  decision.nurture_fact_key = '';
  decision.should_search_knowledge = false;
  decision.should_reveal_price = false;
  decision.should_start_conversion = true;
  decision.should_start_handoff = true;
  decision.decision_missing_entities = [];
  decision.requires_clarification = false;
}

// معالجة إجابة المستخدم على الاعتراض قبل بقية المسارات.
// يمنع ذلك تكرار سؤال الاعتراض الأصلي.
else if (
  objectionFollowupDetected &&
  activeObjection
) {
  if (
    activeObjection === 'objection.price' &&
    objectionResolutionAction ===
      'show_verified_pricing'
  ) {
    decision.objection_followup_handled = true;
    configurePricingDiscovery();
  } else if (
    activeObjection === 'objection.price' &&
    (
      objectionResolutionAction ===
        'close_price_objection' ||
      objectionFollowupPolarity === 'negative'
    )
  ) {
    state.sales_stage = 'post_pricing';
    state.awaiting_entity = '';
    state.last_question = '';

    decision.route_key = 'trial_declined';

    decision.next_best_action =
      'continue_without_pricing';

    decision.action_type =
      'polite_decline_response';

    decision.awaiting_entity = '';

    decision.next_question = '';

    decision.direct_sales_response =
      politeCloseResponses[language];

    decision.should_search_knowledge = false;

    decision.should_reveal_price = false;

    decision.should_start_conversion = false;

    decision.should_start_handoff = false;

    decision.decision_missing_entities = [];

    decision.requires_clarification = false;

    decision.objection_followup_handled = true;
  } else if (
    [
      'objection.online',
      'objection.tutor',
      'objection.schedule'
    ].includes(activeObjection)
  ) {
    configureResolvedObjection();
  }
}

// اكتشاف الاحتياج قبل إظهار السعر.
else if (effectiveIntent === 'pricing.ask') {
  configurePricingDiscovery();
}

// اكتشاف احتياجات الطالب.
else if (
  effectiveIntent === 'student_support.ask'
) {
  state.sales_stage = 'student_support';

  const discoveryFields = [
    'grade_or_age',
    'subject',
    'current_level',
    'difficulty',
    'goal'
  ];

  const missing = allMissing(
    discoveryFields
  );

  const nextField = firstMissing(
    discoveryFields
  );

  if (nextField) {
    const actionMap = {
      grade_or_age: 'ask_grade_or_age',
      subject: 'ask_subject',
      current_level: 'ask_current_level',
      difficulty: 'ask_difficulty',
      goal: 'ask_goal'
    };

    const factMap = {
      grade_or_age: 'personalized_assessment',
      subject: 'curriculum_alignment',
      current_level: 'diagnostic_support',
      difficulty: 'targeted_support',
      goal: 'progress_plan'
    };

    configureQuestion(
      nextField,
      actionMap[nextField],
      factMap[nextField],
      missing
    );
  } else {
    decision.route_key = 'support_ready';

    decision.next_best_action =
      'recommend_personalized_support';

    decision.action_type =
      'consultative_recommendation';

    decision.awaiting_entity = '';

    decision.nurture_fact_key =
      'personalized_learning_plan';

    decision.should_search_knowledge = true;

    decision.decision_missing_entities = [];

    decision.requires_clarification = false;
  }
}

// طلب الحصة التجريبية.
else if (effectiveIntent === 'trial.request') {
  state.sales_stage = 'trial';
  state.trial_interest = true;

  const trialFields = [
    'grade_or_age',
    'subject',
    'country'
  ];

  const missing = allMissing(trialFields);

  const nextField = firstMissing(trialFields);

  if (nextField) {
    const actionMap = {
      grade_or_age: 'ask_grade_or_age',
      subject: 'ask_subject',
      country: 'ask_country'
    };

    const factMap = {
      grade_or_age: 'trial_assessment',
      subject: 'tutor_matching',
      country: 'online_availability'
    };

    configureQuestion(
      nextField,
      actionMap[nextField],
      factMap[nextField],
      missing
    );
  } else {
    decision.route_key = 'conversion';

    decision.next_best_action =
      'start_trial_flow';

    decision.action_type =
      'start_conversion';

    decision.awaiting_entity = '';

    decision.should_start_conversion = true;

    decision.should_search_knowledge = false;
  }
}

// رفض الحصة التجريبية.
else if (effectiveIntent === 'trial.decline') {
  state.sales_stage = 'post_pricing';
  state.trial_interest = false;
  state.awaiting_entity = '';
  state.last_question = '';

  decision.route_key = 'trial_declined';

  decision.next_best_action =
    'continue_without_trial';

  decision.action_type =
    'polite_decline_response';

  decision.awaiting_entity = '';

  decision.next_question = '';

  decision.direct_sales_response =
    politeCloseResponses[language];

  decision.should_search_knowledge = false;

  decision.should_reveal_price = false;

  decision.should_start_conversion = false;

  decision.should_start_handoff = false;

  decision.decision_missing_entities = [];

  decision.requires_clarification = false;
}

// التسجيل.
else if (
  effectiveIntent === 'enrollment.request'
) {
  state.sales_stage = 'enrollment';

  decision.route_key = 'conversion';

  decision.next_best_action =
    'start_enrollment_flow';

  decision.action_type =
    'start_conversion';

  decision.should_start_conversion = true;

  decision.should_search_knowledge = false;
}

// طلب التواصل البشري.
else if (
  effectiveIntent === 'human_handoff.request'
) {
  state.sales_stage = 'handoff';

  decision.route_key = 'handoff';

  decision.next_best_action =
    'start_handoff';

  decision.action_type =
    'human_handoff';

  decision.should_start_handoff = true;

  decision.should_search_knowledge = false;
}

// المعالجة الاستشارية الأولية للاعتراضات.
else if (
  effectiveIntent.startsWith('objection.')
) {
  state.sales_stage = 'objection';

  // قد يصل الاعتراض باعتباره Secondary Intent،
  // لذلك نحفظ النية ذات الأولوية.
  state.objections = unique([
    ...(state.objections || []),
    effectiveIntent
  ]);

  const objectionActions = {
    'objection.price':
      'handle_price_objection',

    'objection.online':
      'handle_online_objection',

    'objection.tutor':
      'handle_tutor_objection',

    'objection.schedule':
      'handle_schedule_objection'
  };

  const objectionQuestions = {
    'objection.price': {
      ar:
        'هل تفضّل أن أوضح لك الباقة الأكثر ملاءمة لاحتياج الطالب؟',

      en:
        'Would you like me to explain which package best suits the student’s needs?',

      fr:
        "Souhaitez-vous que je vous explique quel forfait convient le mieux aux besoins de l’élève ?"
    },

    'objection.online': {
      ar:
        'هل القلق متعلق بتركيز الطالب عبر الإنترنت أم بتفضيل الدروس الحضورية؟',

      en:
        'Is your concern about the student’s online focus or a preference for in-person lessons?',

      fr:
        "Votre préoccupation concerne-t-elle la concentration en ligne ou une préférence pour les cours en personne ?"
    },

    'objection.tutor': {
      ar:
        'هل قلقك متعلق بخبرة المدرس أم بمدى ملاءمته لاحتياجات الطالب؟',

      en:
        'Is your concern about the tutor’s experience or suitability for the student?',

      fr:
        "Votre préoccupation concerne-t-elle l’expérience du tuteur ou son adéquation aux besoins de l’élève ?"
    },

    'objection.schedule': {
      ar:
        'ما الأيام والأوقات التي تناسبكم عادةً؟',

      en:
        'Which days and times usually work for you?',

      fr:
        'Quels jours et horaires vous conviennent généralement ?'
    }
  };

  decision.route_key = 'objection';

  decision.next_best_action =
    objectionActions[effectiveIntent] ||
    'handle_objection';

  decision.action_type =
    'objection_response';

  decision.nurture_fact_key =
    effectiveIntent;

  decision.next_question =
    objectionQuestions[effectiveIntent]?.[language] || '';

  decision.awaiting_entity =
    effectiveIntent === 'objection.schedule'
      ? 'preferred_schedule'
      : 'objection_follow_up';

  decision.should_search_knowledge = false;

  decision.should_reveal_price = false;

  decision.should_start_conversion = false;

  decision.should_start_handoff = false;

  decision.requires_clarification =
    Boolean(decision.next_question);

  state.awaiting_entity =
    decision.awaiting_entity;

  state.last_question =
    decision.next_question;

  state.next_action =
    decision.next_best_action;

  state.questions_asked = unique([
    ...(state.questions_asked || []),
    decision.next_question
  ]);
}

// طلب عرض أو مراجعة البيانات المسجلة.
// يذهب إلى مسار التحويل لعرض الملخص فقط، ولا يشغّل
// التحويل البشري قبل التأكيد النهائي من العميل.
else if (
  effectiveIntent === 'lead.summary.request'
) {
  decision.route_key = 'conversion';

  decision.next_best_action =
    'show_lead_summary';

  decision.action_type =
    'present_lead_summary';

  decision.awaiting_entity = '';

  decision.next_question = '';

  decision.nurture_fact_key = '';

  decision.should_search_knowledge = false;

  decision.should_reveal_price = false;

  decision.should_start_conversion = true;

  decision.should_start_handoff = false;

  decision.decision_missing_entities = [];

  decision.requires_clarification = false;
}

// أسئلة قاعدة المعرفة.
else if (
  [
    'policy.ask',
    'subjects.ask',
    'location.ask',
    'knowledge.ask'
  ].includes(effectiveIntent)
) {
  decision.route_key = 'knowledge';

  decision.next_best_action =
    clean(input.next_action) ||
    'search_knowledge';

  decision.action_type =
    'knowledge_search';

  decision.should_search_knowledge = true;
}

// المسار الاحتياطي الآمن.
else {
  decision.route_key = 'knowledge';

  decision.next_best_action =
    'search_knowledge';

  decision.action_type =
    'knowledge_search';

  decision.should_search_knowledge = true;
}

// إذا اختار مسار الاعتراض سؤالًا سبق طرحه، ننقل
