// يتم ذلك قبل Save Sales State حتى يبقى Redis
// متزامنًا مع السؤال الذي سيظهر للمستخدم.
function configureRepeatRecovery() {
  const candidates = [
    {
      entity: 'grade_or_age',
      action: 'ask_grade_or_age',
      factKey: 'personalized_assessment'
    },
    {
      entity: 'subject',
      action: 'ask_subject',
      factKey: 'curriculum_alignment'
    },
    {
      entity: 'current_level',
      action: 'ask_current_level',
      factKey: 'diagnostic_support'
    },
    {
      entity: 'difficulty',
      action: 'ask_difficulty',
      factKey: 'targeted_support'
    },
    {
      entity: 'goal',
      action: 'ask_goal',
      factKey: 'progress_plan'
    },
    {
      entity: 'country',
      action: 'ask_country',
      factKey: 'online_one_to_one'
    }
  ];

  const missingCandidates = candidates.filter(
    candidate => !hasValue(candidate.entity)
  );

  let candidate = missingCandidates.find(item => {
    const candidateQuestion = clean(
      questions[language][item.entity]
    );

    return (
      !questionsAskedBefore.includes(
        candidateQuestion
      ) &&
      !factsSharedBefore.includes(
        item.factKey
      )
    );
  });

  // إذا كانت كل معلومات الرعاية المتاحة قد استُخدمت،
  // يبقى السؤال الجديد أفضل من إعادة السؤال السابق.
  if (!candidate) {
    candidate = missingCandidates.find(item => {
      const candidateQuestion = clean(
        questions[language][item.entity]
      );

      return !questionsAskedBefore.includes(
        candidateQuestion
      );
    });
  }

  if (!candidate) {
    return false;
  }

  const remainingFields = missingCandidates.map(
    item => item.entity
  );

  const factWasUsed = factsSharedBefore.includes(
    candidate.factKey
  );

  configureQuestion(
    candidate.entity,
    candidate.action,
    factWasUsed ? '' : candidate.factKey,
    remainingFields
  );

  state.sales_stage = 'discovery';
  decision.repeat_recovery_applied = true;

  return true;
}

