    const looksLikeAge =
      /(?:سنة|سنوات|عام|years?|ans?)/i
        .test(message);

    if (looksLikeAge) {
      if (!clean(entities.age)) {
        entities.age = message;
        appliedField = 'age';
        contextualValueApplied = true;
      }
    } else if (!clean(entities.grade)) {
      entities.grade = message;
      appliedField = 'grade';
      contextualValueApplied = true;
    }
  }

  // Handle the remaining discovery fields
  else if (
    contextualFields.has(awaitingEntity)
  ) {
    if (!clean(entities[awaitingEntity])) {
      entities[awaitingEntity] = message;
      appliedField = awaitingEntity;
      contextualValueApplied = true;
