function clean(value) {
  return String(value ?? '').trim();
}

function asObject(value) {
  return value &&
    typeof value === 'object' &&
    !Array.isArray(value)
      ? value
      : {};
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

const input = $json;

const previousState = asObject(
  input.previous_sales_state
);

const currentState = asObject(
  input.sales_state
);

const message = clean(
  input.customer_message ||
  input.original_message ||
  input.chatInput ||
  input.chatinput
);

const awaitingEntity = clean(
  previousState.awaiting_entity ||
  currentState.awaiting_entity
);

const objections = [
  ...asArray(previousState.objections),
  ...asArray(currentState.objections)
]
  .map(clean)
  .filter(Boolean);

let activeObjection =
  objections.length > 0
    ? objections[objections.length - 1]
    : '';

const currentIntent = clean(
  input.primary_intent
);

// إذا صنّف النموذج الرسالة الحالية كاعتراض واضح
if (currentIntent.startsWith('objection.')) {
  activeObjection = currentIntent;
}

const positivePattern =
  /^(نعم|أجل|تمام|موافق|أكيد|طبعا|طبعاً|yes|sure|okay|ok|oui|d'accord)\b/i;

const negativePattern =
  /^(لا|ليس الآن|مش الآن|لا شكرا|لا شكرًا|no|not now|non|pas maintenant)\b/i;

const pricingInterestPattern =
  /(وضح|وضّح|اعرض|الباقة|الباقات|السعر|الأسعار|التكلفة|price|package|pricing|prix|forfait)/i;

const focusPattern =
  /(تركيز|يتشتت|تشتت|انتباه|focus|attention|distract)/i;

const inPersonPattern =
  /(حضوري|وجها لوجه|وجهًا لوجه|in person|présentiel)/i;

const experiencePattern =
  /(خبير|خبرة|متمرس|كفؤ|qualified|experienced|expert|expérimenté)/i;

const matchingPattern =
  /(مناسب|ملائم|مطابقة|يفهم احتياج|matching|suitable|adapté)/i;

const looksLikeNewQuestion =
  /[؟?]/.test(message) ||
  /^(هل|ما|ماذا|كم|متى|أين|اين|كيف|لماذا|why|what|how|when|where|do|does|is|are|quel|quelle|comment|pourquoi)\b/i
    .test(message);

const awaitingObjectionReply =
  awaitingEntity === 'objection_follow_up' ||
  (
    [
      'preferred_schedule',
      'timezone'
    ].includes(awaitingEntity) &&
    activeObjection === 'objection.schedule'
  );

let detected =
  Boolean(message) &&
  Boolean(activeObjection) &&
  awaitingObjectionReply &&
  !looksLikeNewQuestion;

// السماح برد مثل: نعم، وضّح لي الباقة المناسبة
if (
  activeObjection === 'objection.price' &&
  (
    positivePattern.test(message) ||
    pricingInterestPattern.test(message) ||
    currentIntent === 'pricing.ask'
  )
) {
  detected = awaitingObjectionReply;
}

let polarity = 'neutral';

if (positivePattern.test(message)) {
  polarity = 'positive';
} else if (negativePattern.test(message)) {
  polarity = 'negative';
}

let resolutionAction = '';
let responseVariant = '';

if (detected) {
  switch (activeObjection) {
    case 'objection.price':
      if (polarity === 'negative') {
        resolutionAction = 'close_price_objection';
        responseVariant = 'pricing_declined';
      } else {
        resolutionAction = 'show_verified_pricing';
        responseVariant = 'pricing_requested';
      }
      break;

    case 'objection.online':
      resolutionAction = 'resolve_online_objection';

      if (focusPattern.test(message)) {
        responseVariant = 'focus_concern';
      } else if (inPersonPattern.test(message)) {
        responseVariant = 'in_person_preference';
      } else {
        responseVariant = 'general_online_concern';
      }
      break;

    case 'objection.tutor':
      resolutionAction = 'resolve_tutor_objection';

      if (experiencePattern.test(message)) {
        responseVariant = 'tutor_experience';
      } else if (matchingPattern.test(message)) {
        responseVariant = 'tutor_matching';
      } else {
        responseVariant = 'general_tutor_concern';
      }
      break;

    case 'objection.schedule':
      resolutionAction = 'resolve_schedule_objection';
      responseVariant = 'schedule_preference';
      break;
  }
}

return {
  json: {
    ...input,

    objection_followup_detected: detected,
    active_objection: activeObjection,
    objection_followup_value: detected
      ? message
      : '',

    objection_followup_polarity: detected
      ? polarity
      : '',

    objection_resolution_action: detected
      ? resolutionAction
      : '',

    objection_response_variant: detected
      ? responseVariant
      : ''
  }
};

