      /الايميل/,
      /ايميل/,
      /\bemail\b/,
      /e mail/,
      /courriel/
    ]
  },
  {
    field: 'phone',
    patterns: [
      /الهاتف/,
      /رقم الهاتف/,
      /رقم التواصل/,
      /واتساب/,
      /\bphone\b/,
      /whatsapp/,
      /telephone/
    ]
  },
  {
    field: 'country',
    patterns: [
      /الدوله/,
      /البلد/,
      /\bcountry\b/,
      /\bpays\b/
    ]
  },
  {
    field: 'city',
    patterns: [
      /المدينه/,
      /\bcity\b/,
      /\bville\b/
    ]
  },
  {
    field: 'timezone',
    patterns: [
      /المنطقه الزمنيه/,
      /التوقيت/,
      /time zone/,
      /timezone/,
      /fuseau horaire/
    ]
  },
  {
    field: 'preferred_language',
    patterns: [
      /اللغه المفضله/,
      /لغه التواصل/,
      /preferred language/,
      /langue preferee/
    ]
  },
  {
    field: 'grade',
    patterns: [
      /الصف/,
      /المرحله الدراسيه/,
      /\bgrade\b/,
      /niveau scolaire/
    ]
  },
  {
    field: 'subject',
    patterns: [
      /الماده/,
      /الموضوع الدراسي/,
      /\bsubject\b/,
      /matiere/
    ]
  }
];

let detectedField = '';

for (const definition of fieldDefinitions) {
  if (
    definition.patterns.some(pattern =>
      pattern.test(message)
    )
  ) {
    detectedField = definition.field;
    break;
  }
}

const updateVerbPattern =
  /(اريد|اود|حاب|ارغب)?\s*(تعديل|تغيير|تصحيح|تحديث|استبدال)|غير بريدي|صحح بياناتي|update|change|correct|modify|replace|modifier|changer|corriger|mettre a jour/;

const generalLeadDataPattern =
  /(بياناتي|معلوماتي|بيانات التسجيل|بيانات الطالب|my data|my details|registration details|mes donnees|mes informations)/;

const isUpdateRequest =
  updateVerbPattern.test(message) &&
  Boolean(
    detectedField ||
    generalLeadDataPattern.test(message)
  );

const awaitingEntity =
  clean(state.awaiting_entity);

let leadManagementRoute = '';
let leadUpdateField = detectedField;

if (isExactConfirmation) {
  leadManagementRoute = 'confirmation';
} else if (
  awaitingEntity.startsWith('lead_update_')
) {
  leadManagementRoute = 'update_value';

  if (!leadUpdateField) {
    leadUpdateField =
      awaitingEntity.replace('lead_update_', '');
  }
} else if (isUpdateRequest) {
  leadManagementRoute = 'update_request';
}

return [
  {
    json: {
      ...input,

      lead_management_route:
        leadManagementRoute,

      lead_update_field:
        leadUpdateField,

      is_lead_management_message:
        Boolean(leadManagementRoute),

      is_exact_lead_confirmation:
        isExactConfirmation
    }
  }
];
